import axios from "axios";

export const api = axios.create({
  baseURL: "http://127.0.0.1:8001/api",
  withCredentials: true,
});

export const formatApiError = (error) => {
  return (
    error?.response?.data?.detail ||
    error?.message ||
    "Something went wrong"
  );
};

export default api;
